SELECT COUNT(*) FROM (
    SELECT di.devregistry,
        di.wlrangem * (1 - di.wllatvar / 5.0) * (ts.wlsignal + 100) / 100.0 AS wpr_val
    FROM deviceidentity di
    JOIN testsessions ts ON di.devsessionref = ts.sessionregistry
) t WHERE wpr_val > 8.5;

SELECT COUNT(*) FROM (
    SELECT di.devregistry,
